import re
from taf.ul.oam_kpi_calculations.provider import Provider
from taf.ul.oam_kpi_calculations.parsers.swdl.parser import SWDLParser


class Calculator:
    def __init__(self, kpi_names, file_path):
        self.parser = SWDLParser(file_path)
        self.kpi_names = self._get_kpi_names(kpi_names)
        self.kpis = self._get_kpi_instances()

    def calculate(self):
        results = self.parser.parse()
        for kpi in self.kpis:
            start_point_timestamp = results.get(kpi.start_point)
            end_point_timestamp = results.get(kpi.end_point)
            kpi.results.append(self._get_results(start_point_timestamp, end_point_timestamp))

    @staticmethod
    def _get_results(start_point_timestamp, end_point_timestamp):
        if start_point_timestamp and end_point_timestamp:
            delta = end_point_timestamp - start_point_timestamp
        else:
            delta = None

        return {
            'start_point_timestamp': start_point_timestamp,
            'end_point_timestamp': end_point_timestamp,
            'delta': delta
        }

    @staticmethod
    def _get_kpi_names(kpi_names):
        """
        Get KPI names
        :param str, list kpi_names: KPI names
        :return: list of KPI names
        """
        if not isinstance(kpi_names, (list, tuple)):
            kpi_names = re.split(r'\s+', kpi_names)
        kpi_names = [kpi_name.lower() for kpi_name in kpi_names]
        return kpi_names

    def _get_kpi_instances(self):
        """
        Get instance of KPI class.
        :param dict kpi_params: Additional kpi params.
        :return: list of KPI instances
        """
        kpi_instances = []
        for kpi_name in self.kpi_names:
            kpi_instances.append(Provider.provide(kpi_name=kpi_name)())
        return kpi_instances
